# Every configured practice, not a single hardcoded one - same pattern as Detect no-show.
practices = []
try:
    entries = api.files.list(path="PracticeManager/Practices", scope="org")
except Exception:
    entries = []
for entry in entries or []:
    fname = entry.get("name") if isinstance(entry, dict) else entry
    if not fname or not str(fname).endswith(".json"):
        continue
    slug = str(fname)[:-5]
    practice = read_json("PracticeManager/Practices/" + fname, {}) or {}
    if practice:
        practices.append({"slug": slug, "practice": practice})

new_items = []
for p in practices:
    provider = str(p["practice"].get("email_provider") or "outlook")
    seen = read_json("PracticeManager/RescheduleSeen/" + p["slug"] + ".json", []) or []
    seen_ids = {str(x) for x in seen}
    try:
        if provider == "outlook":
            result = api.connectors.invoke(server="m365-mail-read", tool="list_emails", args={"folder": "inbox", "limit": 25, "unreadOnly": True})
            rows = result if isinstance(result, list) else (result or {}).get("value") or (result or {}).get("emails") or []
        else:
            result = api.connectors.invoke(server="google-workspace-gmail", tool="list_messages", args={"maxResults": 25})
            rows = result if isinstance(result, list) else (result or {}).get("messages") or []
    except Exception:
        rows = []
    for row in rows:
        email_id = str(row.get("id") or "")
        if not email_id or email_id in seen_ids:
            continue
        new_items.append({"slug": p["slug"], "practice": p["practice"], "provider": provider, "email_id": email_id})

import json
import re

AI_CLASSIFY_PROMPT = (
    "Read this email to a healthcare clinic. Decide if the sender is a patient asking to move or reschedule "
    "an existing booking (not a new enquiry, not a cancellation with no reschedule request, not anything else). "
    "Return is_reschedule_request (bool) and, only if true, any specific day or time preference the patient "
    "mentioned as preferred_time_note (string, empty if none)."
)
AI_CLASSIFY_HINT = '{"is_reschedule_request": false, "preferred_time_note": ""}'

AI_DRAFT_PROMPT = (
    "You are drafting a short, warm reply on behalf of a healthcare clinic to a patient who asked to reschedule "
    "their booking. Offer the real available times given, in the tone instructed. Never give clinical advice, "
    "diagnosis or interpretation. Keep it under 120 words."
)
AI_DRAFT_HINT = '{"subject": "", "body": ""}'


def read_json(path, default=None):
    try:
        raw = api.files.read(file=path)
    except Exception:
        return default
    try:
        return json.loads(raw)
    except Exception:
        return default


def write_json(path, data):
    api.files.put(file=path, content=json.dumps(data, indent=2, sort_keys=True))


def extract_sender_email(row):
    sender = row.get("sender") or row.get("from") or ""
    if isinstance(sender, dict):
        addr = ((sender.get("emailAddress") or {}).get("address") or sender.get("address") or "")
        if addr:
            return str(addr).lower()
        sender = json.dumps(sender)
    m = re.search(r"[\w.+-]+@[\w-]+\.[\w.-]+", str(sender))
    return m.group(0).lower() if m else ""


def extract_id(link):
    if not isinstance(link, dict):
        return ""
    url = ((link.get("links") or {}).get("self")) or ""
    m = re.search(r"/(\d+)(?:$|\?)", str(url))
    return m.group(1) if m else ""


def format_time(iso):
    return str(iso or "").replace("T", " ").replace("Z", " UTC")


item = params.get("item") or {}
slug = item.get("slug") or ""
practice = item.get("practice") or {}
provider = item.get("provider") or "outlook"
email_id = item.get("email_id") or ""
outcome = "skipped"

if slug and email_id:
    seen_path = "PracticeManager/RescheduleSeen/" + slug + ".json"
    seen = read_json(seen_path, []) or []
    seen_set = {str(x) for x in seen}

    try:
        if provider == "outlook":
            full = api.connectors.invoke(server="m365-mail-read", tool="get_email", args={"id": email_id})
        else:
            full = api.connectors.invoke(server="google-workspace-gmail", tool="get_message", args={"id": email_id})
    except Exception:
        full = {}
    full = full if isinstance(full, dict) else {}
    body_text = str(full.get("body") or full.get("bodyPreview") or full.get("snippet") or "")
    sender_email = extract_sender_email(full)

    try:
        classified = api.ai.extract(prompt=AI_CLASSIFY_PROMPT, input=body_text[:4000], schema_hint=AI_CLASSIFY_HINT)
    except Exception:
        classified = {}
    classified = classified if isinstance(classified, dict) else {}

    if not classified.get("is_reschedule_request"):
        seen_set.add(email_id)
        write_json(seen_path, sorted(seen_set))
        outcome = "not_a_reschedule_request"
    elif not sender_email:
        seen_set.add(email_id)
        write_json(seen_path, sorted(seen_set))
        outcome = "no_sender_email"
    else:
        patients = []
        try:
            found = api.connectors.invoke(server="cliniko-patients", tool="list_patients", args={"q": ["email:=" + sender_email]})
            patients = (found or {}).get("patients") or []
        except Exception:
            patients = []

        if len(patients) != 1:
            # Zero or ambiguous (more than one patient sharing an email) - never guess. Leave unseen so a human
            # can be asked; this skill's own patient-resolution rule ("never guess a match") applies here too.
            api.workq.create(
                title="Reschedule request needs a patient match: " + sender_email,
                scope="org",
                description=(
                    "An email from " + sender_email + " looks like a reschedule request, but "
                    + ("no Cliniko patient" if not patients else str(len(patients)) + " Cliniko patients")
                    + " matched that email address. Match it by hand."
                ),
                priority="normal",
                assignee_ids=[practice.get("reviewer_id")] if practice.get("reviewer_id") else None,
                labels=["healthcare-practice-management", "reschedule", "needs-match"],
            )
            outcome = "patient_not_resolved"
        else:
            patient = patients[0]
            patient_id = str(patient.get("id") or "")
            patient_name = (str(patient.get("first_name") or "") + " " + str(patient.get("last_name") or "")).strip() or sender_email

            upcoming = []
            try:
                appts = api.connectors.invoke(
                    server="cliniko-scheduling", tool="list_individual_appointments",
                    args={"q": ["patient_id:=" + patient_id], "sort": "starts_at:asc", "per_page": 20},
                )
                rows = (appts or {}).get("individual_appointments") or []
                for r in rows:
                    if not r.get("cancelled_at"):
                        upcoming.append(r)
            except Exception:
                upcoming = []

            if not upcoming:
                seen_set.add(email_id)
                write_json(seen_path, sorted(seen_set))
                outcome = "no_upcoming_appointment"
            else:
                appt = upcoming[0]
                business_id = extract_id(appt.get("business"))
                practitioner_id = extract_id(appt.get("practitioner"))
                appointment_type_id = extract_id(appt.get("appointment_type"))

                slots = []
                if business_id and practitioner_id and appointment_type_id:
                    try:
                        avail = api.connectors.invoke(
                            server="cliniko-scheduling", tool="get_available_times",
                            args={"business_id": business_id, "practitioner_id": practitioner_id, "appointment_type_id": appointment_type_id},
                        )
                        raw_slots = avail if isinstance(avail, list) else (avail or {}).get("available_times") or []
                        for s in raw_slots[:3]:
                            t = s.get("appointment_start") if isinstance(s, dict) else s
                            if t:
                                slots.append(format_time(t))
                    except Exception:
                        slots = []

                tone = (practice.get("policy") or {}).get("tone") or "warm, concise, no jargon"
                try:
                    drafted = api.ai.extract(
                        prompt=AI_DRAFT_PROMPT,
                        input=json.dumps({
                            "patient_name": patient_name,
                            "current_time": format_time(appt.get("starts_at")),
                            "available_times": slots,
                            "preferred_time_note": classified.get("preferred_time_note") or "",
                            "tone": tone,
                        }),
                        schema_hint=AI_DRAFT_HINT,
                    )
                except Exception:
                    drafted = {}
                drafted = drafted if isinstance(drafted, dict) else {}
                subject = drafted.get("subject") or "Rescheduling your appointment"
                body = drafted.get("body") or (
                    "Hi " + patient_name + ", happy to move your booking. Let us know which of these times suits: "
                    + ", ".join(slots)
                )

                description = (
                    "**Patient:** " + patient_name + "  \n"
                    "**Current appointment:** " + format_time(appt.get("starts_at")) + "  \n"
                    "**Proposed times:** " + (", ".join(slots) if slots else "none found") + "  \n\n"
                    "**Drafted subject:** " + subject + "  \n\n"
                    "**Drafted message:**\n\n" + body
                )

                reviewer = practice.get("reviewer_id") or ""
                workq_item = api.workq.create(
                    title="Reschedule request: " + patient_name,
                    scope="org",
                    description=description,
                    priority="normal",
                    assignee_ids=[reviewer] if reviewer else None,
                    labels=["healthcare-practice-management", "reschedule"],
                )
                workq_id = workq_item["id"]
                api.workq.attach_form(todo_id=workq_id, form_id=params["approval_form"])

                # Reuses the no-show pair's existing draft-file folder and shape on purpose: Apply no-show
                # follow-up decision reads a hardcoded PracticeManager/NoShowDrafts/<todo_id>.json path, and
                # changing that path would mean editing tested code we don't own. The folder name is now stale
                # for this trigger - a known, accepted trade-off, not an oversight.
                write_json("PracticeManager/NoShowDrafts/" + workq_id + ".json", {
                    "slug": slug,
                    "appointment_id": str(appt.get("id") or ""),
                    "patient_id": patient_id,
                    "patient_name": patient_name,
                    "email": sender_email,
                    "subject": subject,
                    "body": body,
                })

                seen_set.add(email_id)
                write_json(seen_path, sorted(seen_set))
                outcome = "requested_approval"
